"use client";

import { LayoutGroup } from "motion/react";
import { useId, useState } from "react";

import { BlockFrame } from "../parts/block-frame";
import { BillingToggle } from "./shared/billing-toggle";
import { formatCents, plural } from "./shared/money";
import {
  type Billing,
  holdsSeats,
  type PlanId,
  PLANS,
  seatPriceFor,
  smallestPlanFor,
} from "./shared/plans";
import { SEAT_STOPS } from "./pricing-calculator/data";
import { PlanCard } from "./pricing-calculator/plan-card";
import { SeatPicker } from "./pricing-calculator/seat-picker";

/**
 * A pricing section for Fernhill: pick a team size and a billing period, and
 * three plans show their per-seat price and the total for that team. The
 * Recommended badge and the selection frame travel to the plan that fits.
 */
export function PricingCalculator({ className }: { className?: string }) {
  const titleId = useId();
  const groupId = useId();
  const [index, setIndex] = useState(5);
  const [billing, setBilling] = useState<Billing>("yearly");
  const [picked, setPicked] = useState<PlanId | null>(null);

  const seats = SEAT_STOPS[index] ?? 1;
  const recommended = smallestPlanFor(seats);
  // A plan the person chose stays chosen until the team outgrows it.
  const pickedPlan = PLANS.find((plan) => plan.id === picked);
  const chosen =
    pickedPlan && holdsSeats(pickedPlan, seats) ? pickedPlan : recommended;
  const monthly = seatPriceFor(chosen, billing) * seats;

  const fitLimit = (limit: number) => {
    const at = SEAT_STOPS.indexOf(limit);
    if (at >= 0) setIndex(at);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div className="flex flex-col gap-6 p-5 @2xl:p-8">
        <header className="flex flex-col gap-1">
          <h2 id={titleId} className="text-xl font-semibold tracking-tight">
            Pay for the practitioners you have
          </h2>
          <p className="text-sm text-muted-foreground">
            Every plan includes the booking page, reminders and patient records.
            Front desk staff are free.
          </p>
        </header>

        <div className="grid items-end gap-x-8 gap-y-4 @2xl:grid-cols-[1fr_auto]">
          <SeatPicker index={index} onIndexChange={setIndex} />
          <BillingToggle
            value={billing}
            onValueChange={setBilling}
            className="mb-6 self-start @2xl:self-end"
          />
        </div>

        <p aria-live="polite" className="sr-only">
          {`${chosen.name} for ${plural(seats, "practitioner")}: ${formatCents(monthly)} a month.`}
        </p>

        <LayoutGroup id={groupId}>
          <div className="grid gap-4 @3xl:grid-cols-3">
            {PLANS.map((plan) => (
              <PlanCard
                key={plan.id}
                plan={plan}
                seats={seats}
                billing={billing}
                chosen={plan.id === chosen.id}
                recommended={plan.id === recommended.id}
                groupId={groupId}
                onChoose={() => setPicked(plan.id)}
                onFitLimit={() => fitLimit(plan.seatLimit ?? seats)}
              />
            ))}
          </div>
        </LayoutGroup>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { SegmentedControl } from "@/components/motion/segmented-control";

import { type Billing, YEARLY_SAVING } from "./plans";

const OPTIONS = [
  { value: "monthly" as const, label: "Monthly" },
  {
    value: "yearly" as const,
    label: (
      <span className="inline-flex items-center gap-1.5">
        Yearly
        <span className="text-xs font-semibold text-marketing-green-ink">
          Save {Math.round(YEARLY_SAVING * 100)}%
        </span>
      </span>
    ),
  },
];

/**
 * Switches between monthly and yearly billing and shows the yearly saving.
 * It is a radio group, so arrow keys switch the period.
 */
export function BillingToggle({
  value,
  onValueChange,
  className,
}: {
  value: Billing;
  onValueChange: (value: Billing) => void;
  className?: string;
}) {
  return (
    <SegmentedControl
      aria-label="Billing period"
      options={OPTIONS}
      value={value}
      onValueChange={onValueChange}
      className={className}
    />
  );
}

/** How often a clinic pays. */
export type Billing = "monthly" | "yearly";

/** The three Fernhill plans, smallest first. */
export type PlanId = "solo" | "practice" | "group";

/** One Fernhill plan and what it includes. */
export interface Plan {
  id: PlanId;
  name: string;
  /** Who the plan is for, in a few words. */
  audience: string;
  /** The price of one practitioner seat for one month, billed monthly. */
  seatPrice: number;
  /** The most practitioners the plan holds, or null for no limit. */
  seatLimit: number | null;
  /** Bookings a month the plan includes before each extra booking costs more. */
  bookingsIncluded: number;
}

/** Yearly billing takes this share off every price. */
export const YEARLY_SAVING = 0.2;

/** The cost of each booking past a plan's included amount. */
export const EXTRA_BOOKING_PRICE = 0.03;

/** The plans in size order. */
export const PLANS: Plan[] = [
  {
    id: "solo",
    name: "Solo",
    audience: "One room, a few practitioners",
    seatPrice: 14,
    seatLimit: 3,
    bookingsIncluded: 1_000,
  },
  {
    id: "practice",
    name: "Practice",
    audience: "A busy clinic with a front desk",
    seatPrice: 24,
    seatLimit: 25,
    bookingsIncluded: 10_000,
  },
  {
    id: "group",
    name: "Group",
    audience: "Several clinics under one roof",
    seatPrice: 38,
    seatLimit: null,
    bookingsIncluded: 50_000,
  },
];

/** The price of one seat for one month under a billing period. */
export const seatPriceFor = (plan: Plan, billing: Billing) =>
  billing === "yearly" ? plan.seatPrice * (1 - YEARLY_SAVING) : plan.seatPrice;

/** True when the plan has room for this many practitioners. */
export const holdsSeats = (plan: Plan, seats: number) =>
  plan.seatLimit === null || seats <= plan.seatLimit;

/** The smallest plan that has room for this many practitioners. */
export const smallestPlanFor = (seats: number) =>
  PLANS.find((plan) => holdsSeats(plan, seats)) ?? PLANS[PLANS.length - 1]!;

const CENTS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
const DOLLARS = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});
const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });

/** Rounds an amount to whole cents, so every line of a sum adds up to the shown total. */
export const toCents = (value: number) => Math.round(value * 100) / 100;

/** A dollar amount with cents, such as $1,843.20. */
export const formatCents = (value: number) => CENTS.format(toCents(value));

/** A dollar amount with no cents, such as $240. */
export const formatDollars = (value: number) =>
  DOLLARS.format(Math.round(value));

/** A whole number with thousands separators, such as 12,000. */
export const formatCount = (value: number) => WHOLE.format(Math.round(value));

/** A price that may need cents: $24 stays whole, $19.20 keeps its cents. */
export const formatPrice = (value: number) =>
  Number.isInteger(toCents(value)) ? formatDollars(value) : formatCents(value);

/** Writes a count with its noun, such as "1 seat" or "12 seats". */
export const plural = (count: number, one: string, many = `${one}s`) =>
  `${formatCount(count)} ${count === 1 ? one : many}`;

import type { PlanId } from "../shared/plans";

/** The team sizes the slider stops at, in practitioners. */
export const SEAT_STOPS = [1, 2, 3, 5, 8, 12, 18, 25, 40, 60, 100];

/** The stops that carry a label under the slider. */
export const LABELLED_STOPS = [1, 3, 12, 25, 100];

/** One line of a plan's feature list. */
export interface PlanFeature {
  text: string;
  /** The line shows only from this team size up, such as a perk for larger clinics. */
  fromSeats?: number;
}

/** What each plan lists, in order. Lines with `fromSeats` open and close as the team size moves. */
export const FEATURES = {
  solo: [
    { text: "Online booking page" },
    { text: "Text and email reminders" },
    { text: "One room calendar" },
  ],
  practice: [
    { text: "Everything in Solo" },
    { text: "Up to 8 room calendars" },
    { text: "Front desk check-in" },
    { text: "Shared waiting list across rooms", fromSeats: 8 },
    { text: "Rota planning for part-time staff", fromSeats: 18 },
  ],
  group: [
    { text: "Everything in Practice" },
    { text: "Unlimited rooms and clinics" },
    { text: "Reports across every clinic" },
    { text: "Single sign-on for staff", fromSeats: 25 },
    { text: "A named account manager", fromSeats: 40 },
  ],
} satisfies Record<PlanId, PlanFeature[]>;

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { RollingText } from "@/components/blocks/parts/rolling-text";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatCents, formatPrice, plural } from "../shared/money";
import {
  type Billing,
  holdsSeats,
  type Plan,
  seatPriceFor,
} from "../shared/plans";
import { FEATURES, type PlanFeature } from "./data";

// The frame and the badge travel between cards on one spring with a little give,
// because they follow the slider rather than confirm a press.
const TRAVEL: Transition = {
  type: "spring",
  stiffness: 380,
  damping: 32,
  mass: 0.9,
};
const FADE: Transition = { duration: 0.18 };
const INSTANT: Transition = { duration: 0 };

/** Props for one plan card. `groupId` keeps the travelling frame inside one block. */
export interface PlanCardProps {
  plan: Plan;
  seats: number;
  billing: Billing;
  chosen: boolean;
  recommended: boolean;
  groupId: string;
  onChoose: () => void;
  /** Sets the team size to this plan's limit. */
  onFitLimit: () => void;
}

/**
 * One plan with its per-seat price, the total for the chosen team, an action
 * and a feature list. A plan too small for the team says so and offers to
 * drop to its limit instead of hiding.
 */
export function PlanCard({
  plan,
  seats,
  billing,
  chosen,
  recommended,
  groupId,
  onChoose,
  onFitLimit,
}: PlanCardProps) {
  const reduceMotion = useReducedMotion();
  const fits = holdsSeats(plan, seats);
  const perSeat = seatPriceFor(plan, billing);
  const monthly = perSeat * seats;
  const billed =
    billing === "yearly"
      ? `Billed ${formatCents(monthly * 12)} a year`
      : "Billed every month";
  const all: PlanFeature[] = FEATURES[plan.id];
  const features = all.filter(
    (feature) => feature.fromSeats === undefined || seats >= feature.fromSeats,
  );

  return (
    <article
      className={cn(
        "relative flex flex-col gap-4 rounded-xl border border-border p-5",
        !fits && "text-muted-foreground",
      )}
    >
      {chosen ? (
        <motion.span
          aria-hidden="true"
          layoutId={`${groupId}-frame`}
          transition={reduceMotion ? INSTANT : TRAVEL}
          className="pointer-events-none absolute -inset-px rounded-xl border-2 border-chart-1"
        />
      ) : null}
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <h3 className="text-base font-semibold text-foreground">
            {plan.name}
          </h3>
          <p className="text-sm text-muted-foreground">{plan.audience}</p>
        </div>
        {recommended ? (
          <motion.span
            layoutId={`${groupId}-badge`}
            transition={reduceMotion ? INSTANT : TRAVEL}
            className="shrink-0 rounded-full bg-marketing-blue-surface px-2.5 py-0.5 text-xs font-semibold text-marketing-blue-ink"
          >
            Recommended
          </motion.span>
        ) : null}
      </div>

      <div>
        <p className="flex items-baseline gap-1.5">
          <RollingText
            text={formatPrice(perSeat)}
            className="text-3xl font-semibold tracking-tight text-foreground"
          />
          <span className="text-sm text-muted-foreground">
            per seat a month
          </span>
        </p>
        <div className="mt-1 min-h-10 text-sm">
          <AnimatePresence mode="wait" initial={false}>
            <motion.p
              key={fits ? `fit-${billing}` : "too-small"}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={reduceMotion ? INSTANT : FADE}
            >
              {fits ? (
                <>
                  <span className="text-foreground">
                    <RollingText
                      text={formatCents(monthly)}
                      className="font-medium"
                    />{" "}
                    a month for {plural(seats, "seat")}
                  </span>
                  <span className="block text-muted-foreground">{billed}</span>
                </>
              ) : (
                <span className="text-muted-foreground">
                  Holds up to {plural(plan.seatLimit ?? 0, "practitioner")}.
                </span>
              )}
            </motion.p>
          </AnimatePresence>
        </div>
      </div>

      {fits ? (
        <Button
          type="button"
          variant={chosen ? "default" : "outline"}
          aria-pressed={chosen}
          onClick={onChoose}
        >
          {chosen ? <CheckIcon aria-hidden="true" /> : null}
          {chosen ? `${plan.name} chosen` : `Choose ${plan.name}`}
        </Button>
      ) : (
        <Button type="button" variant="secondary" onClick={onFitLimit}>
          Use {plural(plan.seatLimit ?? 0, "seat")}
        </Button>
      )}

      <ul
        className="flex flex-col text-sm"
        aria-label={`${plan.name} includes`}
      >
        <AnimatePresence initial={false}>
          {features.map((feature) => (
            <motion.li
              key={feature.text}
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={reduceMotion ? INSTANT : TRAVEL}
              className="overflow-hidden"
            >
              <span className="flex items-start gap-2 py-1">
                <CheckIcon
                  aria-hidden="true"
                  className={cn(
                    "mt-0.5 size-4 shrink-0",
                    fits ? "text-chart-2" : "text-muted-foreground",
                  )}
                />
                <span className={fits ? "text-foreground" : undefined}>
                  {feature.text}
                </span>
              </span>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </article>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

