import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import { PlusIcon } from "@/components/blocks/parts/icons";
import { Slider } from "@/components/motion/slider";
import { Button } from "@/components/ui/button";
import { MinusIcon } from "../shared/icons";
import { plural } from "../shared/money";
import { StopLabels } from "../shared/stop-labels";
import { LABELLED_STOPS, SEAT_STOPS } from "./data";

/** Props for the team size picker. `index` is a position in `SEAT_STOPS`. */
export interface SeatPickerProps {
  index: number;
  onIndexChange: (index: number) => void;
}

const LAST = SEAT_STOPS.length - 1;

/**
 * Picks a team size from fixed stops. The slider is a native range input, so
 * arrows, Home, End and the Page keys all move between stops; the minus and
 * plus buttons step one stop each.
 */
export function SeatPicker({ index, onIndexChange }: SeatPickerProps) {
  const seats = SEAT_STOPS[index] ?? 1;
  return (
    <div className="flex items-end gap-3">
      <Button
        type="button"
        variant="outline"
        size="icon"
        className="mb-6 shrink-0"
        aria-label="Fewer practitioners"
        disabled={index === 0}
        onClick={() => onIndexChange(Math.max(0, index - 1))}
      >
        <MinusIcon aria-hidden="true" />
      </Button>
      <div className="min-w-0 flex-1 -mx-3 overflow-x-clip px-3">
        <Slider
          label="Practitioners on your team"
          min={0}
          max={LAST}
          value={index}
          onValueChange={onIndexChange}
          formatValue={() => plural(seats, "practitioner")}
        />
        <StopLabels
          stops={LABELLED_STOPS.map((stop) => ({
            at: SEAT_STOPS.indexOf(stop) / LAST,
            label: String(stop),
          }))}
        />
      </div>
      <Button
        type="button"
        variant="outline"
        size="icon"
        className="mb-6 shrink-0"
        aria-label="More practitioners"
        disabled={index === LAST}
        onClick={() => onIndexChange(Math.min(LAST, index + 1))}
      >
        <PlusIcon aria-hidden="true" />
      </Button>
    </div>
  );
}

"use client";

import { ownIcon, packIcon } from "@/components/blocks/parts/icons";

